        int n = sc.nextInt();
        List<Integer> nums = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nums.add(sc.nextInt());
        }

        List<Integer> picked = new ArrayList<>();
        Iterator<Integer> it = nums.iterator();
        while (it.hasNext()) {
            int x = it.next();
            if (x >= 5) {
                picked.add(x);
            }
        }
        System.out.println("原柜子里有 " + nums.size() + " 件");
        System.out.println("够大的有 " + picked.size() + " 件");
        System.out.println("它们是 " + picked);
    }
}

